/* ============================================================
   APEX // DYNO — design system
   ============================================================ */
:root {
  --bg-0: #02060f;
  --bg-1: #050d1c;
  --bg-2: #07152a;
  --panel: rgba(8, 21, 40, 0.72);
  --panel-solid: #08162b;
  --panel-raised: rgba(13, 31, 56, 0.82);
  --line: rgba(104, 174, 235, 0.14);
  --line-soft: rgba(104, 174, 235, 0.08);
  --line-strong: rgba(56, 189, 248, 0.42);
  --cyan: #38bdf8;
  --cyan-bright: #7dd3fc;
  --cyan-deep: #0ea5e9;
  --teal: #22d3ee;
  --blue: #3b82f6;
  --indigo: #6366f1;
  --orange: #fb923c;
  --amber: #fbbf24;
  --red: #f43f5e;
  --green: #34d399;
  --text: #e8f4ff;
  --text-soft: #b8cee5;
  --muted: #7691ad;
  --muted-2: #526b86;
  --mono: "DejaVu Sans Mono", "Liberation Mono", ui-monospace, monospace;
  --sans: "Lato", "Segoe UI", "Liberation Sans", system-ui, sans-serif;
  --radius: 14px;
  --shadow: 0 22px 55px rgba(0, 0, 0, 0.48);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
  background: var(--bg-0);
}

body {
  font-family: var(--sans);
  color: var(--text);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button, input, output { font: inherit; }
button { color: inherit; }
::selection { background: rgba(56, 189, 248, 0.35); color: #fff; }

/* Scrollbars */
.rail::-webkit-scrollbar,
.panel-body::-webkit-scrollbar { width: 5px; height: 5px; }
.rail::-webkit-scrollbar-track { background: transparent; }
.rail::-webkit-scrollbar-thumb { background: rgba(56, 189, 248, 0.22); border-radius: 99px; }

/* ============================================================
   Ambient background
   ============================================================ */
.app-shell {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  height: 100vh;
  min-height: 620px;
  background:
    radial-gradient(1100px 620px at 16% -8%, rgba(14, 84, 155, 0.24), transparent 62%),
    radial-gradient(900px 600px at 96% 10%, rgba(59, 130, 246, 0.12), transparent 60%),
    radial-gradient(1000px 700px at 50% 120%, rgba(99, 102, 241, 0.12), transparent 65%),
    linear-gradient(180deg, #050d1c 0%, #030814 48%, #02060f 100%);
}

.ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}

.ambient::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(90, 160, 220, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(90, 160, 220, 0.045) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: radial-gradient(ellipse 90% 80% at 50% 40%, black 20%, transparent 78%);
  -webkit-mask-image: radial-gradient(ellipse 90% 80% at 50% 40%, black 20%, transparent 78%);
  opacity: 0.55;
}

.orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.34;
  animation: orbFloat 18s ease-in-out infinite alternate;
}
.orb-a { width: 520px; height: 520px; left: -160px; top: -160px; background: #0b5cab; }
.orb-b { width: 460px; height: 460px; right: -130px; top: 16%; background: #1d4ed8; animation-delay: -7s; opacity: 0.24; }
.orb-c { width: 560px; height: 400px; left: 38%; bottom: -240px; background: #4f46e5; animation-delay: -12s; opacity: 0.2; }

@keyframes orbFloat {
  from { transform: translate3d(0, 0, 0) scale(1); }
  to { transform: translate3d(26px, 32px, 0) scale(1.08); }
}

.grain {
  position: absolute;
  inset: 0;
  opacity: 0.032;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}

/* ============================================================
   Top bar
   ============================================================ */
.topbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 26px;
  height: 78px;
  padding: 0 22px;
  border-bottom: 1px solid rgba(96, 165, 250, 0.12);
  background: linear-gradient(180deg, rgba(7, 18, 35, 0.88), rgba(4, 12, 26, 0.6));
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  position: relative;
  z-index: 5;
}
.topbar::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(56, 189, 248, 0.34) 24%, rgba(99, 102, 241, 0.26) 64%, transparent);
}

.brand { display: flex; align-items: center; gap: 12px; flex: 0 0 auto; }
.brand-mark {
  width: 44px; height: 44px;
  color: var(--cyan);
  filter: drop-shadow(0 0 14px rgba(56, 189, 248, 0.5));
  animation: brandGlow 4s ease-in-out infinite alternate;
}
.brand-mark svg { width: 100%; height: 100%; display: block; }
@keyframes brandGlow {
  from { filter: drop-shadow(0 0 8px rgba(56, 189, 248, 0.3)); }
  to { filter: drop-shadow(0 0 18px rgba(56, 189, 248, 0.65)); }
}
.brand-title {
  font-size: 21px;
  font-weight: 900;
  letter-spacing: 0.16em;
  line-height: 1;
  white-space: nowrap;
}
.brand-title span { color: var(--cyan); text-shadow: 0 0 22px rgba(56, 189, 248, 0.45); }
.brand-sub {
  margin-top: 5px;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.24em;
  color: var(--muted);
  white-space: nowrap;
}

.preset-cluster { margin: 0 auto; display: flex; flex-direction: column; align-items: center; gap: 5px; }
.cluster-label {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.26em;
  color: var(--muted-2);
}
.preset-switch {
  display: flex;
  gap: 3px;
  padding: 3px;
  border: 1px solid rgba(96, 165, 250, 0.13);
  border-radius: 11px;
  background: rgba(4, 12, 26, 0.62);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
}
.preset-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 7px 12px;
  background: transparent;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, box-shadow 0.2s, color 0.2s;
}
.preset-btn:hover { background: rgba(56, 189, 248, 0.07); }
.preset-btn.active {
  background: linear-gradient(180deg, rgba(30, 96, 160, 0.5), rgba(12, 45, 86, 0.58));
  border-color: rgba(56, 189, 248, 0.32);
  box-shadow: 0 0 18px rgba(56, 189, 248, 0.13), inset 0 1px 0 rgba(255, 255, 255, 0.07);
}
.preset-btn.active::after {
  content: "";
  position: absolute;
  left: 22%; right: 22%; bottom: -3px;
  height: 1.5px;
  border-radius: 2px;
  background: var(--cyan);
  box-shadow: 0 0 9px var(--cyan);
}
.preset-kicker {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted);
  border: 1px solid rgba(104, 174, 235, 0.16);
  border-radius: 4px;
  padding: 2px 4px;
  line-height: 1;
}
.preset-btn.active .preset-kicker { color: var(--cyan-bright); border-color: rgba(56, 189, 248, 0.3); }
.preset-name {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text-soft);
  white-space: nowrap;
}
.preset-btn.active .preset-name { color: #fff; }

.top-actions { display: flex; align-items: center; gap: 9px; flex: 0 0 auto; }
.live-pill {
  display: flex; align-items: center; gap: 7px;
  padding: 7px 10px;
  border: 1px solid rgba(52, 211, 153, 0.2);
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.06);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.14em;
  color: #7ee8c4;
  white-space: nowrap;
}
.live-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 9px var(--green);
  animation: pulseDot 1.8s ease-in-out infinite;
}
.live-pill.off { border-color: rgba(148, 163, 184, 0.2); background: rgba(148, 163, 184, 0.05); color: var(--muted); }
.live-pill.off .live-dot { background: var(--muted); box-shadow: none; animation: none; }
@keyframes pulseDot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.42; transform: scale(0.82); }
}

.audio-btn, .ignition-btn {
  display: flex; align-items: center; gap: 8px;
  height: 36px;
  padding: 0 13px;
  border-radius: 9px;
  border: 1px solid rgba(104, 174, 235, 0.18);
  background: linear-gradient(180deg, rgba(17, 39, 68, 0.8), rgba(7, 19, 37, 0.8));
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.12em;
  color: var(--text-soft);
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}
.audio-btn:hover, .ignition-btn:hover { border-color: rgba(56, 189, 248, 0.4); background: linear-gradient(180deg, rgba(24, 54, 92, 0.9), rgba(9, 25, 48, 0.9)); }
.audio-btn.on { border-color: rgba(56, 189, 248, 0.45); color: #dff7ff; box-shadow: 0 0 18px rgba(56, 189, 248, 0.12), inset 0 0 18px rgba(56, 189, 248, 0.06); }
.audio-btn .audio-icon { width: 16px; height: 16px; color: var(--muted); }
.audio-btn.on .audio-icon { color: var(--cyan); filter: drop-shadow(0 0 6px rgba(56, 189, 248, 0.7)); }
.audio-btn.on .wave-1, .audio-btn.on .wave-2 { animation: wavePulse 1.1s ease-in-out infinite alternate; }
.audio-btn.on .wave-2 { animation-delay: -0.5s; }
@keyframes wavePulse { from { opacity: 0.35; } to { opacity: 1; } }

.ignition-btn {
  border-color: rgba(56, 189, 248, 0.34);
  background: linear-gradient(180deg, rgba(20, 82, 137, 0.72), rgba(8, 41, 77, 0.85));
  color: #d9f4ff;
  box-shadow: 0 0 24px rgba(56, 189, 248, 0.1), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.ignition-btn:hover { box-shadow: 0 0 30px rgba(56, 189, 248, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.1); }
.ignition-led {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 10px var(--green);
}
.ignition-btn.off { border-color: rgba(148, 163, 184, 0.2); background: linear-gradient(180deg, rgba(22, 33, 48, 0.8), rgba(9, 17, 29, 0.9)); color: var(--muted); }
.ignition-btn.off .ignition-led { background: var(--red); box-shadow: 0 0 10px rgba(244, 63, 94, 0.7); }

/* ============================================================
   Workspace + rails
   ============================================================ */
.workspace {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: 306px minmax(0, 1fr) 334px;
  gap: 12px;
  padding: 12px 14px 12px;
}

.rail {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-right: 2px;
  scrollbar-width: thin;
  scrollbar-color: rgba(56, 189, 248, 0.22) transparent;
}

.panel {
  position: relative;
  flex: 0 0 auto;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(155deg, rgba(16, 37, 66, 0.78) 0%, rgba(7, 19, 37, 0.86) 54%, rgba(5, 14, 29, 0.9) 100%);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.045);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  overflow: hidden;
}
.panel::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background:
    radial-gradient(340px 100px at 14% 0%, rgba(56, 189, 248, 0.09), transparent 70%),
    linear-gradient(90deg, transparent, rgba(56, 189, 248, 0.06) 40%, transparent 78%);
  opacity: 0.9;
}
.panel::after {
  content: "";
  position: absolute;
  top: 0; left: 14px; right: 14px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(125, 211, 252, 0.34), transparent);
  pointer-events: none;
}

.panel-head {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 12px 14px 11px;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.panel-head:hover .panel-title { color: #fff; }
.panel-glyph {
  display: grid; place-items: center;
  width: 28px; height: 28px;
  border-radius: 8px;
  border: 1px solid rgba(56, 189, 248, 0.2);
  background: linear-gradient(180deg, rgba(30, 80, 132, 0.32), rgba(9, 29, 56, 0.5));
  color: var(--cyan);
  flex: 0 0 auto;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}
.panel-glyph svg { width: 15px; height: 15px; }
.panel-title-wrap { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1; }
.panel-title {
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-soft);
  transition: color 0.2s;
}
.panel-sub {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.08em;
  color: var(--muted-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.panel-chevron {
  width: 7px; height: 7px;
  border-right: 1.5px solid var(--muted);
  border-bottom: 1.5px solid var(--muted);
  transform: rotate(45deg) translateY(-2px);
  transition: transform 0.3s;
  margin-right: 3px;
  flex: 0 0 auto;
}
.panel.collapsed .panel-chevron { transform: rotate(-45deg) translateY(-2px); }

.panel-body {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows 0.34s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.25s;
}
.panel-inner {
  min-height: 0;
  overflow: hidden;
  padding: 2px 14px 13px;
  display: flex;
  flex-direction: column;
  gap: 11px;
}
.panel.collapsed .panel-body { grid-template-rows: 0fr; opacity: 0; }
.panel.collapsed .panel-inner { padding-top: 0; padding-bottom: 0; }

/* ============================================================
   Controls
   ============================================================ */
.rpm-hero {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 10px 12px 9px;
  border: 1px solid rgba(56, 189, 248, 0.14);
  border-radius: 10px;
  background:
    radial-gradient(180px 60px at 78% 0%, rgba(56, 189, 248, 0.12), transparent 70%),
    linear-gradient(180deg, rgba(10, 30, 56, 0.66), rgba(5, 15, 30, 0.7));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}
.rpm-hero-top { display: flex; align-items: baseline; justify-content: space-between; }
.field-label { font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.18em; color: var(--muted); }
.rpm-hero-value { display: flex; align-items: baseline; gap: 4px; }
.rpm-hero-value strong {
  font-family: var(--mono);
  font-size: 25px;
  font-weight: 700;
  letter-spacing: -0.04em;
  color: #f2fbff;
  text-shadow: 0 0 18px rgba(56, 189, 248, 0.35);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.rpm-hero-value em { font-family: var(--mono); font-style: normal; font-size: 8px; color: var(--muted); letter-spacing: 0.1em; }
.rpm-track {
  position: relative;
  height: 6px;
  border-radius: 99px;
  background: rgba(2, 8, 18, 0.85);
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.7);
  overflow: hidden;
}
.rpm-fill {
  position: absolute; inset: 0 auto 0 0;
  width: 8%;
  border-radius: 99px;
  background: linear-gradient(90deg, #0ea5e9, #38bdf8 55%, #a5f3fc);
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.65);
  transition: width 0.12s linear;
}
.rpm-redline {
  position: absolute; top: -1px; bottom: -1px;
  width: 2px;
  background: var(--red);
  box-shadow: 0 0 8px rgba(244, 63, 94, 0.8);
  left: 85%;
}
.rpm-ticks {
  position: absolute; inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(255, 255, 255, 0.09) calc(10% - 1px), rgba(255, 255, 255, 0.09) 10%);
  pointer-events: none;
}
.rpm-meta { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 7px; color: var(--muted-2); letter-spacing: 0.08em; }
.redline-label { color: rgba(251, 113, 133, 0.8); }

.control { display: flex; flex-direction: column; gap: 7px; }
.control-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.control-head label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.035em;
  color: var(--text-soft);
  cursor: pointer;
}
.control-head output {
  font-family: var(--mono);
  font-size: 9.5px;
  font-weight: 700;
  color: var(--cyan-bright);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
  white-space: nowrap;
}
.control.compact { gap: 6px; }

.range {
  --fill: 30%;
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 16px;
  margin: 0;
  background: transparent;
  cursor: pointer;
}
.range::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--cyan) 0%, var(--cyan) var(--fill), rgba(120, 160, 200, 0.12) var(--fill), rgba(120, 160, 200, 0.12) 100%);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.6);
}
.range::-moz-range-track {
  height: 4px;
  border-radius: 99px;
  background: rgba(120, 160, 200, 0.12);
}
.range::-moz-range-progress {
  height: 4px;
  border-radius: 99px;
  background: var(--cyan);
}
.range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 13px; height: 13px;
  margin-top: -4.5px;
  border-radius: 50%;
  border: 2px solid #9fe8ff;
  background: #0a2744;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.12), 0 0 12px rgba(56, 189, 248, 0.8);
  transition: transform 0.15s, box-shadow 0.15s;
}
.range:hover::-webkit-slider-thumb { transform: scale(1.14); box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.16), 0 0 18px rgba(56, 189, 248, 0.95); }
.range:active::-webkit-slider-thumb { transform: scale(1.2); }
.range::-moz-range-thumb {
  width: 10px; height: 10px;
  border-radius: 50%;
  border: 2px solid #9fe8ff;
  background: #0a2744;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.8);
}
.range.tiny { height: 13px; }
.range.tiny::-webkit-slider-runnable-track { height: 3px; }
.range.tiny::-webkit-slider-thumb { width: 10px; height: 10px; margin-top: -3.5px; }

.range-scale { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 6.8px; letter-spacing: 0.12em; color: var(--muted-2); margin-top: -3px; }

.panel-foot-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding-top: 1px; }
.ghost-btn {
  border: 1px solid rgba(104, 174, 235, 0.18);
  background: rgba(9, 26, 50, 0.5);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.12em;
  border-radius: 6px;
  padding: 6px 9px;
  cursor: pointer;
  transition: all 0.2s;
}
.ghost-btn:hover { color: var(--cyan-bright); border-color: rgba(56, 189, 248, 0.4); background: rgba(14, 45, 82, 0.6); }
.micro-note { font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; color: var(--muted-2); }
.micro-note.center { text-align: center; }

/* Fluid panel */
.switch-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.flow-switch {
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid rgba(104, 174, 235, 0.12);
  background: rgba(6, 19, 38, 0.5);
  border-radius: 8px;
  padding: 8px 8px;
  font-size: 8.5px;
  font-weight: 600;
  color: var(--muted);
  cursor: pointer;
  text-align: left;
  transition: all 0.2s;
}
.flow-switch i {
  margin-left: auto;
  width: 16px; height: 8px;
  border-radius: 99px;
  background: rgba(120, 160, 200, 0.18);
  position: relative;
  flex: 0 0 auto;
  transition: background 0.2s;
}
.flow-switch i::after {
  content: "";
  position: absolute;
  top: 1px; left: 1px;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #6e8aa5;
  transition: transform 0.2s, background 0.2s;
}
.flow-switch.active { color: var(--text-soft); border-color: rgba(56, 189, 248, 0.24); background: rgba(13, 42, 75, 0.55); }
.flow-switch.active i { background: rgba(56, 189, 248, 0.35); }
.flow-switch.active i::after { transform: translateX(8px); background: var(--cyan); box-shadow: 0 0 7px var(--cyan); }
.switch-dot { width: 6px; height: 6px; border-radius: 50%; flex: 0 0 auto; }
.switch-dot.intake { background: #38bdf8; box-shadow: 0 0 7px rgba(56, 189, 248, 0.7); }
.switch-dot.combustion { background: #fbbf24; box-shadow: 0 0 7px rgba(251, 191, 36, 0.7); }
.switch-dot.exhaust { background: #fb923c; box-shadow: 0 0 7px rgba(251, 146, 60, 0.7); }
.switch-dot.thermal { background: #a78bfa; box-shadow: 0 0 7px rgba(167, 139, 250, 0.7); }

.legend-block {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 10px;
  border: 1px solid rgba(104, 174, 235, 0.1);
  border-radius: 8px;
  background: rgba(3, 11, 24, 0.4);
}
.legend-row { display: flex; align-items: center; gap: 7px; font-size: 8.5px; color: var(--muted); }
.legend-row b { margin-left: auto; font-family: var(--mono); font-size: 7.5px; font-weight: 400; color: var(--muted-2); }
.legend-swatch { width: 14px; height: 4px; border-radius: 99px; }
.legend-swatch.intake { background: linear-gradient(90deg, #1d4ed8, #67e8f9); box-shadow: 0 0 7px rgba(56, 189, 248, 0.5); }
.legend-swatch.combustion { background: linear-gradient(90deg, #fbbf24, #f97316); box-shadow: 0 0 7px rgba(251, 146, 60, 0.5); }
.legend-swatch.exhaust { background: linear-gradient(90deg, #f97316, #dc2626); box-shadow: 0 0 7px rgba(239, 68, 68, 0.45); }
.flow-readout {
  display: flex;
  align-items: baseline;
  gap: 5px;
  padding-top: 1px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}
.flow-readout strong { margin-left: auto; font-size: 16px; color: var(--cyan-bright); letter-spacing: -0.02em; text-shadow: 0 0 14px rgba(56, 189, 248, 0.4); }
.flow-readout em { font-style: normal; font-size: 7.5px; color: var(--muted); }

/* ============================================================
   Stage
   ============================================================ */
.stage {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.stage-head {
  flex: 0 0 auto;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
  padding: 0 4px 0 6px;
}
.engine-ident { min-width: 0; }
.eyebrow {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.24em;
  color: var(--muted);
  margin-bottom: 4px;
}
.eyebrow-line { width: 18px; height: 1px; background: linear-gradient(90deg, var(--cyan), transparent); box-shadow: 0 0 6px var(--cyan); }
.engine-ident h1 {
  margin: 0;
  font-size: clamp(20px, 2.2vw, 31px);
  line-height: 1.05;
  font-weight: 900;
  letter-spacing: 0.01em;
  color: #f2fbff;
  text-shadow: 0 0 32px rgba(56, 189, 248, 0.16);
  white-space: nowrap;
}
.engine-spec {
  margin-top: 5px;
  font-family: var(--mono);
  font-size: 7.8px;
  letter-spacing: 0.16em;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.telemetry { display: flex; align-items: flex-end; gap: 8px; flex: 0 0 auto; }
.tach-block { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; padding-right: 4px; }
.tach-number { display: flex; align-items: baseline; gap: 4px; }
.tach-number strong {
  font-family: var(--mono);
  font-size: 23px;
  line-height: 1;
  color: #eafaff;
  letter-spacing: -0.05em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 16px rgba(56, 189, 248, 0.3);
}
.tach-number span { font-family: var(--mono); font-size: 7px; color: var(--muted); letter-spacing: 0.1em; }
.tach-bar {
  position: relative;
  width: 128px;
  height: 4px;
  border-radius: 99px;
  background: rgba(2, 8, 18, 0.9);
  overflow: hidden;
}
.tach-bar i {
  display: block;
  height: 100%;
  width: 8%;
  border-radius: 99px;
  background: linear-gradient(90deg, #0ea5e9, #7dd3fc);
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.65);
  transition: width 0.12s linear;
}
.tach-bar b { position: absolute; top: 0; bottom: 0; width: 2px; left: 85%; background: var(--red); box-shadow: 0 0 6px var(--red); }
.t-chip {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 58px;
  padding: 6px 9px 5px;
  border: 1px solid rgba(104, 174, 235, 0.12);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(11, 30, 55, 0.62), rgba(5, 15, 30, 0.56));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
}
.t-chip span { font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.14em; color: var(--muted-2); }
.t-chip strong { font-family: var(--mono); font-size: 14px; line-height: 1.1; color: var(--text); font-variant-numeric: tabular-nums; }
.t-chip em { font-family: var(--mono); font-style: normal; font-size: 6.5px; color: var(--muted); margin-top: -1px; }

.viewport {
  position: relative;
  flex: 1 1 auto;
  min-height: 300px;
  border: 1px solid rgba(56, 189, 248, 0.19);
  border-radius: 16px;
  overflow: hidden;
  background:
    radial-gradient(ellipse 70% 70% at 50% 44%, rgba(13, 58, 105, 0.24), transparent 72%),
    linear-gradient(180deg, #061226 0%, #040c1a 58%, #030914 100%);
  box-shadow:
    0 26px 70px rgba(0, 0, 0, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.045),
    inset 0 0 80px rgba(2, 8, 18, 0.7);
}
.viewport::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(56, 189, 248, 0.22), transparent 16%) top left / 50px 1px no-repeat,
    linear-gradient(180deg, rgba(56, 189, 248, 0.22), transparent 16%) top left / 1px 50px no-repeat,
    linear-gradient(270deg, rgba(56, 189, 248, 0.22), transparent 16%) top right / 50px 1px no-repeat,
    linear-gradient(180deg, rgba(56, 189, 248, 0.22), transparent 16%) top right / 1px 50px no-repeat,
    linear-gradient(90deg, rgba(56, 189, 248, 0.18), transparent 16%) bottom left / 50px 1px no-repeat,
    linear-gradient(0deg, rgba(56, 189, 248, 0.18), transparent 16%) bottom left / 1px 50px no-repeat,
    linear-gradient(270deg, rgba(56, 189, 248, 0.18), transparent 16%) bottom right / 50px 1px no-repeat,
    linear-gradient(0deg, rgba(56, 189, 248, 0.18), transparent 16%) bottom right / 1px 50px no-repeat;
  opacity: 0.8;
}
#engineCanvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; z-index: 0; }
.viewport-overlay { position: absolute; inset: 0; z-index: 2; pointer-events: none; }

.vp-top-left { position: absolute; top: 14px; left: 16px; display: flex; align-items: center; gap: 6px; }
.vp-chip {
  display: flex; align-items: center; gap: 6px;
  padding: 5px 8px;
  border: 1px solid rgba(56, 189, 248, 0.2);
  border-radius: 5px;
  background: rgba(3, 14, 30, 0.65);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.12em;
  color: var(--cyan-bright);
  backdrop-filter: blur(4px);
}
.vp-chip.muted { color: var(--muted); border-color: rgba(104, 174, 235, 0.1); }
.vp-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); animation: pulseDot 2s infinite; }
.vp-top-right { position: absolute; top: 14px; right: 16px; display: flex; flex-direction: column; align-items: flex-end; gap: 3px; }
.vp-label { font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.2em; color: var(--muted-2); }
.vp-phase {
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--cyan-bright);
  text-shadow: 0 0 14px rgba(56, 189, 248, 0.55);
}
.vp-legend {
  position: absolute;
  left: 16px; bottom: 16px;
  display: flex;
  gap: 12px;
  padding: 6px 9px;
  border: 1px solid rgba(104, 174, 235, 0.1);
  border-radius: 6px;
  background: rgba(3, 12, 26, 0.55);
  backdrop-filter: blur(4px);
}
.vp-legend span { display: flex; align-items: center; gap: 5px; font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.1em; color: var(--muted); }
.lg { width: 5px; height: 5px; border-radius: 50%; }
.lg.intake { background: #38bdf8; box-shadow: 0 0 6px #38bdf8; }
.lg.combustion { background: #fbbf24; box-shadow: 0 0 6px #fbbf24; }
.lg.exhaust { background: #f97316; box-shadow: 0 0 6px #f97316; }
.lg.spark { background: #e0f2fe; box-shadow: 0 0 6px #7dd3fc; }
.vp-bottom-right {
  position: absolute;
  right: 16px; bottom: 16px;
  display: flex;
  gap: 10px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  color: var(--muted-2);
}

.phase-strip {
  position: absolute;
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%);
  display: flex;
  gap: 3px;
  padding: 3px;
  border: 1px solid rgba(104, 174, 235, 0.1);
  border-radius: 8px;
  background: rgba(3, 12, 26, 0.7);
  backdrop-filter: blur(6px);
}
.phase-seg {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 8px;
  border-radius: 5px;
  border: 1px solid transparent;
  transition: background 0.25s, border-color 0.25s, box-shadow 0.25s;
}
.phase-seg b { font-family: var(--mono); font-size: 6.5px; color: var(--muted-2); }
.phase-seg span { font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.08em; color: var(--muted); }
.phase-seg i { width: 4px; height: 4px; border-radius: 50%; background: rgba(120, 160, 200, 0.2); }
.phase-seg.active { background: rgba(14, 58, 103, 0.65); border-color: rgba(56, 189, 248, 0.26); box-shadow: inset 0 0 14px rgba(56, 189, 248, 0.08); }
.phase-seg.active b { color: var(--cyan); }
.phase-seg.active span { color: #dff7ff; }
.phase-seg.active i { background: var(--cyan); box-shadow: 0 0 7px var(--cyan); }
.phase-seg[data-phase="power"].active { background: rgba(120, 53, 15, 0.42); border-color: rgba(251, 146, 60, 0.35); }
.phase-seg[data-phase="power"].active b, .phase-seg[data-phase="power"].active span { color: #ffd8b0; }
.phase-seg[data-phase="power"].active i { background: var(--orange); box-shadow: 0 0 8px var(--orange); }
.phase-seg[data-phase="exhaust"].active { background: rgba(91, 27, 32, 0.4); border-color: rgba(244, 63, 94, 0.3); }
.phase-seg[data-phase="exhaust"].active b, .phase-seg[data-phase="exhaust"].active span { color: #ffc0c8; }
.phase-seg[data-phase="exhaust"].active i { background: var(--red); box-shadow: 0 0 8px var(--red); }

.viewport-warning {
  position: absolute;
  top: 52px;
  left: 50%;
  transform: translateX(-50%) translateY(-8px);
  z-index: 3;
  padding: 6px 12px;
  border-radius: 6px;
  border: 1px solid rgba(244, 63, 94, 0.4);
  background: rgba(61, 12, 23, 0.8);
  color: #ffb3bf;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.14em;
  box-shadow: 0 0 26px rgba(244, 63, 94, 0.18);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s, transform 0.3s;
  white-space: nowrap;
}
.viewport-warning.show { opacity: 1; transform: translateX(-50%) translateY(0); }

.scanlines {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  background: repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.022) 0px, rgba(255, 255, 255, 0.022) 1px, transparent 1px, transparent 4px);
  mix-blend-mode: overlay;
  opacity: 0.45;
}

/* ============================================================
   Acoustics panel
   ============================================================ */
.audio-head-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.audio-state { display: flex; align-items: center; gap: 7px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; color: var(--muted); }
.signal-bars { display: flex; align-items: flex-end; gap: 2px; height: 10px; }
.signal-bars i { display: block; width: 2px; border-radius: 1px; background: var(--cyan); opacity: 0.3; animation: signal 1.1s ease-in-out infinite alternate; }
.signal-bars i:nth-child(1) { height: 4px; animation-delay: -0.2s; }
.signal-bars i:nth-child(2) { height: 8px; animation-delay: -0.5s; }
.signal-bars i:nth-child(3) { height: 6px; animation-delay: -0.8s; }
.signal-bars i:nth-child(4) { height: 9px; animation-delay: -0.35s; }
.audio-state.live .signal-bars i { opacity: 0.95; }
@keyframes signal { from { transform: scaleY(0.4); opacity: 0.35; } to { transform: scaleY(1); opacity: 1; } }
.volume-wrap { display: flex; align-items: center; gap: 6px; min-width: 120px; }
.volume-wrap output { font-family: var(--mono); font-size: 7.5px; color: var(--muted); min-width: 25px; text-align: right; }
.mini-icon-btn {
