  border-radius: 6px;
  border: 1px solid rgba(104, 174, 235, 0.14);
  background: rgba(8, 24, 46, 0.55);
  color: var(--muted);
  cursor: pointer;
  transition: all 0.2s;
  flex: 0 0 auto;
}
.mini-icon-btn:hover { color: var(--cyan); border-color: rgba(56, 189, 248, 0.35); }
.mini-icon-btn svg { width: 13px; height: 13px; }
.mini-icon-btn.muted { color: var(--red); border-color: rgba(244, 63, 94, 0.3); }

.viz-stack { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.viz-block {
  min-width: 0;
  border: 1px solid rgba(104, 174, 235, 0.12);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(2, 10, 22, 0.86), rgba(4, 14, 28, 0.8));
  overflow: hidden;
  box-shadow: inset 0 0 24px rgba(0, 0, 0, 0.5);
}
.viz-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  padding: 5px 7px 3px;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.1em;
  color: var(--muted-2);
}
.viz-head b { font-weight: 400; color: var(--muted); font-size: 5.8px; white-space: nowrap; }
.viz-block canvas { display: block; width: 100%; height: 62px; }
.viz-block.off canvas { opacity: 0.4; }

.record-row { display: flex; align-items: center; gap: 8px; }
.record-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 32px;
  border-radius: 8px;
  border: 1px solid rgba(244, 63, 94, 0.26);
  background: linear-gradient(180deg, rgba(78, 17, 32, 0.42), rgba(35, 9, 19, 0.48));
  color: #ffb8c3;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.14em;
  cursor: pointer;
  transition: all 0.2s;
}
.record-btn:hover { border-color: rgba(244, 63, 94, 0.5); box-shadow: 0 0 18px rgba(244, 63, 94, 0.12); }
.record-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--red); box-shadow: 0 0 8px rgba(244, 63, 94, 0.7); }
.record-btn.recording { background: linear-gradient(180deg, rgba(127, 29, 29, 0.7), rgba(69, 10, 10, 0.72)); border-color: rgba(248, 113, 113, 0.65); color: #fff; animation: recPulse 1.6s ease-in-out infinite; }
.record-btn.recording .record-dot { animation: pulseDot 1s infinite; background: #fff; box-shadow: 0 0 10px #fff; }
@keyframes recPulse { 0%, 100% { box-shadow: 0 0 0 rgba(244, 63, 94, 0); } 50% { box-shadow: 0 0 22px rgba(244, 63, 94, 0.3); } }
.record-time { font-family: var(--mono); font-size: 8px; color: var(--muted); min-width: 34px; text-align: right; }

/* ============================================================
   Diagnostics
   ============================================================ */
.diag-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.diag-stat {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 7px 8px 6px;
  border: 1px solid rgba(104, 174, 235, 0.1);
  border-radius: 7px;
  background: linear-gradient(180deg, rgba(9, 28, 53, 0.52), rgba(4, 14, 28, 0.5));
}
.diag-stat span { font-family: var(--mono); font-size: 5.8px; letter-spacing: 0.1em; color: var(--muted-2); white-space: nowrap; }
.diag-stat strong { font-family: var(--mono); font-size: 15px; line-height: 1.15; color: var(--text); font-variant-numeric: tabular-nums; }
.diag-stat em { font-family: var(--mono); font-style: normal; font-size: 6px; color: var(--muted); margin-top: -1px; }

.health-list { display: flex; flex-direction: column; gap: 6px; }
.health-row { display: flex; flex-direction: column; gap: 3px; }
.health-top { display: flex; align-items: baseline; justify-content: space-between; font-size: 8.5px; color: var(--muted); }
.health-top b { font-family: var(--mono); font-size: 7.5px; color: var(--text-soft); font-weight: 400; }
.health-track { height: 3px; border-radius: 99px; background: rgba(2, 8, 18, 0.8); overflow: hidden; box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.6); }
.health-track i { display: block; height: 100%; width: 0%; border-radius: 99px; background: linear-gradient(90deg, #22d3ee, #38bdf8); box-shadow: 0 0 7px rgba(56, 189, 248, 0.5); transition: width 0.2s, background 0.3s; }
.health-row.warn .health-track i { background: linear-gradient(90deg, #fbbf24, #fb923c); box-shadow: 0 0 8px rgba(251, 146, 60, 0.55); }
.health-row.danger .health-track i { background: linear-gradient(90deg, #fb7185, #f43f5e); box-shadow: 0 0 8px rgba(244, 63, 94, 0.6); }
.health-row.warn .health-top b { color: #ffd29c; }
.health-row.danger .health-top b { color: #ffb3bf; }

.warning-zone {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 7px 8px;
  border: 1px solid rgba(104, 174, 235, 0.1);
  border-radius: 7px;
  background: rgba(3, 11, 24, 0.36);
}
.warning-title { display: flex; align-items: center; justify-content: space-between; font-family: var(--mono); font-size: 5.8px; letter-spacing: 0.12em; color: var(--muted-2); }
.warning-title b { color: var(--muted); font-weight: 400; }
.warning-list { display: flex; flex-wrap: wrap; gap: 4px; min-height: 16px; }
.warning-empty { font-family: var(--mono); font-size: 6.5px; color: rgba(52, 211, 153, 0.65); letter-spacing: 0.06em; }
.warn-chip {
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.08em;
  padding: 3px 5px;
  border-radius: 4px;
  border: 1px solid rgba(251, 146, 60, 0.3);
  background: rgba(120, 53, 15, 0.28);
  color: #ffd0a6;
  animation: warnBlink 2.2s ease-in-out infinite;
}
.warn-chip.danger { border-color: rgba(244, 63, 94, 0.36); background: rgba(88, 15, 28, 0.35); color: #ffb3bf; }
@keyframes warnBlink { 0%, 100% { opacity: 1; } 50% { opacity: 0.65; } }

.cyl-pressure { display: flex; flex-direction: column; gap: 5px; }
.cyl-pressure-head { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 5.8px; letter-spacing: 0.12em; color: var(--muted-2); }
.cyl-pressure-head b { font-weight: 400; color: var(--muted); }
.cyl-bars { display: flex; align-items: flex-end; gap: 4px; height: 38px; padding: 4px 5px 0; border-radius: 6px; background: rgba(2, 8, 18, 0.4); border: 1px solid rgba(104, 174, 235, 0.07); }
.cyl-bar { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 2px; height: 100%; justify-content: flex-end; }
.cyl-bar i { display: block; width: 100%; max-width: 14px; border-radius: 2px 2px 1px 1px; background: linear-gradient(180deg, #7dd3fc, #0ea5e9); box-shadow: 0 0 6px rgba(56, 189, 248, 0.28); transition: height 0.1s linear; }
.cyl-bar span { font-family: var(--mono); font-size: 5.5px; color: var(--muted-2); }

.diag-foot { display: flex; justify-content: space-between; align-items: center; font-family: var(--mono); font-size: 6.5px; color: var(--muted-2); letter-spacing: 0.06em; }
.diag-foot span { display: flex; align-items: center; gap: 5px; }
.dot { width: 5px; height: 5px; border-radius: 50%; }
.dot.ok { background: var(--green); box-shadow: 0 0 6px var(--green); }
.dot.warn { background: var(--amber); box-shadow: 0 0 6px var(--amber); }
.dot.bad { background: var(--red); box-shadow: 0 0 6px var(--red); }

/* ============================================================
   Status bar, toast, hint
   ============================================================ */
.statusbar {
  flex: 0 0 29px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 18px;
  border-top: 1px solid rgba(96, 165, 250, 0.08);
  background: rgba(3, 9, 20, 0.72);
  font-family: var(--mono);
  font-size: 6.8px;
  letter-spacing: 0.1em;
  color: var(--muted-2);
  backdrop-filter: blur(8px);
}
.status-left, .status-right { display: flex; align-items: center; gap: 16px; }
.statusbar b { font-weight: 400; color: var(--muted); }
.status-dot { display: inline-block; width: 4px; height: 4px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 6px var(--cyan); margin-right: 6px; }
.fps b { color: var(--green); }

.toast {
  position: fixed;
  z-index: 60;
  left: 50%;
  bottom: 54px;
  transform: translateX(-50%) translateY(14px);
  padding: 10px 16px;
  border: 1px solid rgba(56, 189, 248, 0.3);
  border-radius: 9px;
  background: rgba(7, 24, 46, 0.92);
  color: var(--text-soft);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.1em;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.55), 0 0 24px rgba(56, 189, 248, 0.1);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s, transform 0.3s;
  max-width: min(90vw, 460px);
  text-align: center;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

.audio-hint {
  position: fixed;
  z-index: 40;
  left: 50%;
  bottom: 40px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border: 1px solid rgba(56, 189, 248, 0.24);
  border-radius: 99px;
  background: rgba(5, 20, 40, 0.82);
  color: var(--cyan-bright);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.14em;
  backdrop-filter: blur(10px);
  box-shadow: 0 0 28px rgba(56, 189, 248, 0.12);
  pointer-events: none;
  transition: opacity 0.4s, transform 0.4s;
}
.audio-hint.hidden { opacity: 0; transform: translateX(-50%) translateY(10px); }
.hint-pulse { width: 6px; height: 6px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); animation: pulseDot 1.4s infinite; }

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 1320px) {
  .workspace { grid-template-columns: 288px minmax(0, 1fr) 312px; }
  .preset-name { font-size: 10px; }
  .t-chip { min-width: 52px; }
  .brand-sub { display: none; }
}

@media (max-width: 1160px) {
  body { overflow: auto; }
  .app-shell { height: auto; min-height: 100vh; }
  .topbar { flex-wrap: wrap; height: auto; padding: 12px 16px; gap: 12px; }
  .preset-cluster { order: 3; width: 100%; margin: 0; }
  .preset-switch { width: 100%; }
  .preset-btn { flex: 1; justify-content: center; }
  .top-actions { margin-left: auto; }
  .workspace {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    height: auto;
    padding: 12px;
  }
  .stage { grid-column: 1 / -1; order: -1; height: auto; }
  .viewport { min-height: 540px; }
  .rail { overflow: visible; }
  .rail-left { order: 1; }
  .rail-right { order: 2; }
  .statusbar { flex: 0 0 auto; height: 30px; }
}

@media (max-width: 820px) {
  .topbar { padding: 10px 12px; }
  .brand-mark { width: 36px; height: 36px; }
  .brand-title { font-size: 18px; }
  .live-pill { display: none; }
  .workspace { grid-template-columns: 1fr; padding: 10px; gap: 10px; }
  .stage { order: -1; }
  .rail-left { order: 1; }
  .rail-right { order: 2; }
  .viewport { min-height: 420px; }
  .stage-head { flex-direction: column; align-items: flex-start; gap: 9px; }
  .telemetry { width: 100%; justify-content: space-between; }
  .t-chip { flex: 1; min-width: 0; }
  .engine-ident h1 { font-size: 23px; }
  .vp-legend { display: none; }
  .phase-strip { bottom: 10px; }
  .phase-seg { padding: 5px 6px; }
  .phase-seg span { display: none; }
  .phase-seg b { font-size: 7px; }
  .vp-bottom-right { bottom: 10px; font-size: 6px; }
  .status-right .hide-md { display: none; }
}

@media (max-width: 560px) {
  .top-actions { gap: 6px; width: 100%; }
  .audio-btn, .ignition-btn { flex: 1; justify-content: center; height: 34px; }
  .preset-kicker { display: none; }
  .preset-btn { padding: 7px 5px; }
  .preset-name { font-size: 9px; }
  .stage-head { padding: 0 2px; }
  .engine-ident h1 { font-size: 20px; }
  .engine-spec { font-size: 6.8px; letter-spacing: 0.08em; }
  .telemetry { gap: 5px; }
  .tach-block { display: none; }
  .t-chip { padding: 5px 7px 4px; }
  .t-chip strong { font-size: 12px; }
  .viewport { min-height: 390px; }
  .vp-top-left .vp-chip.muted { display: none; }
  .phase-strip { display: none; }
  .vp-bottom-right { display: none; }
  .status-left .hide-sm { display: none; }
  .statusbar { font-size: 6px; padding: 0 10px; }
  .audio-hint { font-size: 6.5px; padding: 7px 10px; white-space: nowrap; }
}

@media (max-height: 760px) and (min-width: 1161px) {
  .topbar { height: 66px; }
  .workspace { padding-top: 9px; }
  .stage-head { padding-bottom: 0; }
  .engine-ident h1 { font-size: 22px; }
  .viewport { min-height: 260px; }
  .panel-inner { gap: 8px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

content.text:
Now simulation.js. Let's carefully design.

Presets with all fields.

Compute geometry config for renderer:
```
preset.layout, cylinders, bankAngle (deg), firing phases.
```

For inline-4: throwPhases [0, 540, 180, 360]? Firing order 1-3-4-2: cylinder1 fires at 0, cylinder3 at 180, cylinder4 at 360, cylinder2 at 540. So cylinder index 0 phase 0, 1 phase 540, 2 phase 180, 3 phase 360. Set `throwPhases: [0, 540, 180, 360]`.

For V6: pairs 3, throw phases [0, 240, 480]? Firing every 120 with 6 cylinders. If pairs share throws, each pair has two cylinders offset 360; left phases [0,240,480], right [360,600,840]? That yields firing events at 0,120,240,360,480,600. Hmm pair 1 left 0, right 360; pair 2 left 240, right 600; pair 3 left 480, right 840=120. Events at 0,120,240,360,480,600. Good. So throws [0,240,480], right +360. But crank pin position phases [0,240,480] means crank throws at 0,240,480; that's fine (120° even firing). For visual piston motion, throws spaced 120, good.
For V8: throws [0, 90, 180, 270] (cross-plane), right +360. Events 0,90,180,270,360,450,540,630 => every 90. Great.
For inline-4 throws [0, 540, 180, 360] => events at 0,180,360,540. Good.
Cycle offsets: for inline, same as throw phases; for V, left=throw, right=throw+360.

Crank pin shared in pair. Renderer computes world pin from throw phase. Good.

But pressure at cycle angle for right cylinder = crankAngle + throw + 360. At its TDC cycle 360? Let's see: right cycle = crank + throw + 360. When crank+throw = 0 (piston TDC), cycle=360 (TDC power). Good. When crank+throw=180 (BDC), cycle=540 (BDC exhaust). That's correct for a cylinder on power stroke while left is on intake. Great.

For left cycle = crank+throw, at crank+throw=0 cycle=0 (TDC intake). Both at TDC. Good.

So piston position from crank angle + throw, cycle from crank + throw + (0 or 360). For inline each cylinder phase unique.

Now simulation update:

- Keep crankAngle 0..720. At rpm 850, 850*6=5100 deg/s. 720 cycle in 0.14s; 4-stroke cycles 7 per sec. Fine.
- engine running initial true.
- targetRpm idle 900. smoothing.
- rev limiter: `if (this.rpm > this.preset.redline) { this.limiterActive = true; ... }`. Since target may be 10500, let rpm go above redline but clamp at limiter and cut fuel. Use `this.rpm = Math.min(this.rpm, redline + 80)` with oscillation? The slider can exceed; engine bounces at redline. Implement:
```
if (running) {
  let target = targetRpm;
  if (target > redline) target = redline;
  const response = target > rpm ? 2.6 : 1.6;
  rpm += (target-rpm)*min(1, dt*response);
  if (targetRpm > redline && rpm > redline*0.985) {
    limiterActive = true;
    fuelCut = (Math.sin(time*110)>0.1);
  }
}
```
This means if target 10500 but redline 9000, rpm sits near 9000 and fuel cuts, giving limiter bounce. Good. Display limiter active. But user might expect rev past redline; redline is max. Fine.

- Ignition off: `rpm += (0-rpm)*dt*0.8`, running false, fuelCut false, no combustion. crankAngle still advances.

- `this.crankAngle += rpm*6*dt`. `cycleAngle = crankAngle % 720`.

- Per cylinder update. We need pressure function. Use `this.preset.turbo`.

- Spark flash: compute sparkAngle = (360 - timing + 720) % 720. `sparkDist = ((cycle - sparkAngle + 720) % 720)`; spark = running && sparkDist < 10 ? 1 - sparkDist/10 : 0. But this means spark flash every cycle at spark timing. Good.
- combustion intensity: pressure normalized. `combo = clamp((p - 18)/60, 0,1) * (cycle>340 && cycle<500 ? 1 : 0)` plus ignition glow. Use pressure model.

- Intake/exhaust lift: with fuel cut? Valve still moves. If not running and rpm low, no lift? cams still rotate if engine spinning. Use lift regardless of running but scale by rpm>10. Good.
- Valve float: global floatFactor = smoothstep(springRate*0.94, redline*1.02, rpm). Add bounce `Math.sin(time*90 + i)*floatFactor*0.15`. Effective lift = camLift*(1-float*0.55) + bounce*0.25. Clamp.
- Piston slap: global `slap` 0-1; renderer adds jitter.

- Cylinder pressure: per cylinder with injection pulse variation. Also if fuelCut, multiply combustion by 0.1.

- Peak pressure track: max over cylinders, decay slowly.
- Torque formula with float and detonation reductions.
- AFR factor etc.
- warning flags.

- `chargeVelocity = (0.8 + throttle/100*3 + rpm/redline*4) * (1+turbo*0.4)` m/s. Realistic-ish.

- `exhaustTemp = 500 + load*4 + rpm/redline*250` maybe.
- `oilTemp`.

- `fuelFlow` maybe not displayed.
- `afrEffective = afr` with injection pulsation variation? Use display.

- `lambda = afr/14.7`.

- `sparkAngle` etc.

- `phaseName` based on cycle of cylinder 0 (or active cylinder). For viewport phase, use cylinder 0 cycle. At startup, cycle 0 = intake. Good.
- `cyclePhase` object.

- `firingFrequency = rpm/60 * (cylinders/2)`.

- `exhaustPulse` for audio: average pressure.

- `knock` random. Set `this.knock = 0`; if detonation > 0.4 and running, chance `detonation * dt * 12` -> set knock = 1. Decay. Audio can trigger.

- `revLimit` etc.

Preset interpolation when switching? We can smooth slider values via UI. For simulation, set direct. Fine.

Let's code simulation.js.

Need helper clamp, smoothstep, lerp.

Pressure formula details:
```
pressureAt(cycle, index, sim) {
  const CR = this.compression;
  const loadF = this.load/100;
  const thrF = this.throttle/100;
  const boost = 1 + this.preset.turbo * loadF * 0.85;
  const map = (0.26 + 0.74*thrF) * boost + 0.1;
  const vol = 1 + (CR-1)*(1-Math.cos(cycle*DEG))/2;
  let p;
  if (cycle < 180) {
     p = map * (0.9 + 0.1*Math.cos(cycle*DEG)); // slight
  } else if (cycle < 360) {
     p = map * Math.pow(CR/vol, 1.34);
  } else if (cycle < 540) {
     const comp = map * Math.pow(CR/vol, 1.34);
     const opt = 25 - Math.min(8, this.rpm/1400);
     const sparkCenter = 360 + 9 - (this.timing - 25)*0.45;
     const width = 24 + this.injection*0.035 + this.rpm/redline*4;
     const afrFactor = clamp(1.1 - Math.abs(this.afr-12.7)/9, 0.45, 1.08);
     const timingFactor = Math.exp(-Math.pow((this.timing-opt)/17,2));
     const amp = (26 + 44*loadF + 16*thrF) * afrFactor * (0.65+0.35*timingFactor) * boost;
     const comb = this.running ? amp * Math.exp(-Math.pow((cycle-sparkCenter)/width,2)) : 0;
     p = comp + comb;
  } else {
     p = 1.05 + 0.32*loadF*Math.exp(-Math.pow((cycle-575)/45,2)) + 0.12*Math.sin(cycle*DEG*2);
  }
  // pulsation ripple
  const pulse = 1 + (this.injection/100)*0.05*Math.sin((cycle*0.23) + index*2.1);
  if (this.fuelCut) p = cycle>350 && cycle<520 ? p*0.35 : p;
  return Math.max(0.18, p*pulse);
}
```
At cycle 360 with CR 12.5, map 0.5: comp=0.5*12.5^1.34 = 14.8; amp with load .32 thr .22: 26+14+3.5=43.5 * afr .95 * timing .8 * 1 = 33. Peak ~48 bar. Fine. At load 100, amp=86*0.95*1=82 -> peak ~100 bar. Good.

Torque formula:
```
const afrF = clamp(1.12 - Math.abs(this.afr-12.7)/10, .4, 1.05);
const opt = 25 - Math.min(8, this.rpm/1400);
const timingF = Math.exp(-Math.pow((this.timing-opt)/20,2));
const loadF = this.load/100;
const boost = 1 + preset.turbo*loadF*0.9;
const bmep = (3.8 + 10.8*loadF*afrF*timingF) * boost * (1 - valveFloat*0.3) * (1 - detonation*0.25);
```
At idle load 32: 3.8+10.8*.32*.95*.9 ≈ 6.75 bar; torque I4 = 6.75e5*0.002/12.566=107 Nm; power at 900 = 10 kW (13hp). Good.
