164: 
165:     return {
166:       geos,
167:       w, h, marginX, spacing, crankY, strokePx, r: r2, rod: rod2, pistonH: pistonH2,
168:       bore, headH, headW, deckY, bottomY, blockX0, blockX1, blockTop, blockBottom,
169:       isVee, units, camAngle
170:     };
171:   }
172: 
173:   ensureFx(cyl) {
174:     if (!cyl._fx) {
175:       cyl._fx = {
176:         intake: [],
177:         exhaust: [],
178:         burn: [],
179:         accI: 0,
180:         accE: 0,
181:         accB: 0,
182:         seed: Math.random() * 100
183:       };
184:     }
185:     return cyl._fx;
186:   }
187: 
188:   updateFx(geo, dt) {
189:     const sim = this.sim;
190:     const fx = this.ensureFx(geo.cyl);
191:     const running = sim.running && sim.rpm > 8;
192:     const dens = sim.density;
193:     const turb = sim.turbulence;
194:     const chamberMid = (geo.deckY + geo.pistonTop) / 2;
195: 
196:     // Spawn intake charge.
197:     if (sim.particlesOn.intake && running && geo.cyl.intakeLift > 0.03) {
198:       fx.accI += dt * (8 + dens * 62) * (0.25 + sim.throttle / 100) * geo.cyl.intakeLift;
199:       const max = 10 + Math.round(dens * 10);
200:       while (fx.accI >= 1) {
201:         fx.accI -= 1;
202:         if (fx.intake.length < max) {
203:           const side = geo.intakeDir;
204:           fx.intake.push({
205:             x: side * (geo.headW * 0.9 + Math.random() * 8),
206:             y: geo.deckY - geo.headH * 0.34 + (Math.random() - 0.5) * 7,
207:             px: 0, py: 0, vx: -side * (50 + Math.random() * 40), vy: 12 + Math.random() * 22,
208:             age: 0, life: 0.85 + Math.random() * 0.55,
209:             size: 1.1 + Math.random() * 1.7,
210:             state: 'runner',
211:             side,
212:             swirl: (Math.random() > 0.5 ? 1 : -1) * (4 + Math.random() * 5),
213:             tint: Math.random()
214:           });
215:         }
216:       }
217:     }
218: 
219:     // Spawn exhaust gas.
220:     if (sim.particlesOn.exhaust && running && geo.cyl.exhaustLift > 0.03) {
221:       fx.accE += dt * (7 + dens * 56) * (0.3 + sim.load / 100) * geo.cyl.exhaustLift;
222:       const max = 9 + Math.round(dens * 10);
223:       while (fx.accE >= 1) {
224:         fx.accE -= 1;
225:         if (fx.exhaust.length < max) {
226:           fx.exhaust.push({
227:             x: (Math.random() - 0.5) * geo.bore * 0.45,
228:             y: geo.deckY + 6 + Math.random() * Math.max(3, geo.chamberH * 0.7),
229:             px: 0, py: 0,
230:             vx: geo.exhaustDir * (18 + Math.random() * 26),
231:             vy: -12 - Math.random() * 24,
232:             age: 0, life: 0.75 + Math.random() * 0.6,
233:             size: 1.2 + Math.random() * 2,
234:             state: 'chamber',
235:             side: geo.exhaustDir,
236:             swirl: 0,
237:             tint: Math.random()
238:           });
239:         }
240:       }
241:     }
242: 
243:     // Spawn combustion flame.
244:     if (sim.particlesOn.combustion && geo.cyl.combustion > 0.12) {
245:       fx.accB += dt * (20 + dens * 120) * geo.cyl.combustion;
246:       const max = 12 + Math.round(dens * 14);
247:       while (fx.accB >= 1) {
248:         fx.accB -= 1;
249:         if (fx.burn.length < max) {
250:           fx.burn.push({
251:             x: (Math.random() - 0.5) * geo.bore * 0.38,
252:             y: geo.deckY + 3 + Math.random() * Math.max(4, geo.chamberH * 0.55),
253:             px: 0, py: 0,
254:             vx: (Math.random() - 0.5) * 90,
255:             vy: 12 + Math.random() * 70,
256:             age: 0, life: 0.3 + Math.random() * 0.42,
257:             size: 1.4 + Math.random() * 2.6,
258:             state: 'burn',
259:             side: 0,
260:             swirl: (Math.random() > 0.5 ? 1 : -1) * (6 + Math.random() * 8),
261:             tint: Math.random()
262:           });
263:         }
264:       }
265:     }
266: 
267:     const updateList = (list, kind) => {
268:       for (let i = list.length - 1; i >= 0; i--) {
269:         const q = list[i];
270:         q.age += dt;
271:         q.px = q.x;
272:         q.py = q.y;
273:         if (kind === 'intake') {
274:           const seatX = geo.intakeDir * geo.bore * 0.27;
275:           if (q.state === 'runner') {
276:             const dx = seatX - q.x;
277:             const dy = geo.deckY - q.y;
278:             const dist = Math.hypot(dx, dy) || 1;
279:             q.vx += (dx / dist) * 300 * dt;
280:             q.vy += (dy / dist) * 300 * dt;
281:             q.vx *= 1 - 2.4 * dt;
282:             q.vy *= 1 - 2.4 * dt;
283:             if (dist < 8 || q.age > 0.42) {
284:               q.state = 'chamber';
285:               q.x = seatX * 0.85;
286:               q.y = geo.deckY + 4;
287:               q.vx = geo.intakeDir * -10;
288:               q.vy = 44;
289:               q.age = Math.min(q.age, 0.2);
290:             }
291:           } else {
292:             const dx = q.x - 0;
293:             const dy = q.y - chamberMid;
294:             q.vx += -dy * q.swirl * dt;
295:             q.vy += dx * q.swirl * dt;
296:             q.vx += (Math.random() - 0.5) * 90 * turb * dt;
297:             q.vy += (Math.random() - 0.5) * 90 * turb * dt;
298:             q.vx *= 1 - 1.7 * dt;
299:             q.vy *= 1 - 1.7 * dt;
300:             const xMax = geo.bore * 0.46;
301:             const yTop = geo.deckY + 2;
302:             const yBot = geo.pistonTop - 2;
303:             if (q.x > xMax) { q.x = xMax; q.vx *= -0.4; }
304:             if (q.x < -xMax) { q.x = -xMax; q.vx *= -0.4; }
305:             if (q.y < yTop) { q.y = yTop; q.vy *= -0.4; }
306:             if (q.y > yBot) { q.y = yBot; q.vy *= -0.4; }
307:           }
308:         } else if (kind === 'exhaust') {
309:           const seatX = geo.exhaustDir * geo.bore * 0.27;
310:           const portX = geo.exhaustDir * (geo.headW * 0.72);
311:           const portY = geo.deckY - geo.headH * 0.34;
312:           if (q.state === 'chamber') {
313:             const dx = seatX - q.x;
314:             const dy = geo.deckY - q.y;
315:             const dist = Math.hypot(dx, dy) || 1;
316:             q.vx += (dx / dist) * 360 * dt;
317:             q.vy += (dy / dist) * 360 * dt;
318:             q.vx *= 1 - 2.3 * dt;
319:             q.vy *= 1 - 2.3 * dt;
320:             if (dist < 9) {
321:               q.state = 'port';
322:               q.x = seatX;
323:               q.y = geo.deckY - 3;
324:               q.vx = geo.exhaustDir * 90;
325:               q.vy = -18;
326:             }
327:           } else if (q.state === 'port') {
328:             const dx = portX - q.x;
329:             const dy = portY - q.y;
330:             const dist = Math.hypot(dx, dy) || 1;
331:             q.vx += (dx / dist) * 300 * dt;
332:             q.vy += (dy / dist) * 300 * dt;
333:             q.vx *= 1 - 2.6 * dt;
334:             q.vy *= 1 - 2.6 * dt;
335:             if (dist < 10) q.state = 'out';
336:           } else {
337:             q.vx += geo.exhaustDir * 80 * dt;
338:             q.vy -= 24 * dt;
339:             q.vx *= 1 - 1.1 * dt;
340:             q.vy *= 1 - 1.1 * dt;
341:           }
342:           q.vx += (Math.random() - 0.5) * 100 * turb * dt;
343:           q.vy += (Math.random() - 0.5) * 100 * turb * dt;
344:         } else {
345:           const dx = q.x - 0;
346:           const dy = q.y - chamberMid;
347:           q.vx += -dy * q.swirl * dt;
348:           q.vy += dx * q.swirl * dt;
349:           q.vx += (Math.random() - 0.5) * 140 * turb * dt;
350:           q.vy += (Math.random() - 0.5) * 140 * turb * dt;
351:           q.vx *= 1 - 2.1 * dt;
352:           q.vy *= 1 - 2.1 * dt;
353:           const xMax = geo.bore * 0.47;
354:           const yTop = geo.deckY + 1;
355:           const yBot = geo.pistonTop - 1;
356:           if (q.x > xMax) { q.x = xMax; q.vx *= -0.35; }
357:           if (q.x < -xMax) { q.x = -xMax; q.vx *= -0.35; }
358:           if (q.y < yTop) { q.y = yTop; q.vy *= -0.35; }
359:           if (q.y > yBot) { q.y = yBot; q.vy *= -0.35; }
360:         }
361:         q.x += q.vx * dt;
362:         q.y += q.vy * dt;
363:         if (q.age > q.life) list.splice(i, 1);
364:       }
365:     };
366: 
367:     updateList(fx.intake, 'intake');
368:     updateList(fx.exhaust, 'exhaust');
369:     updateList(fx.burn, 'burn');
370:   }
371: 
372:   draw(now) {
373:     const ctx = this.ctx;
374:     if (!this.w || !this.h) this.resize();
375:     if (!this.w || !this.h) return;
376:     let dt = (now - this.last) / 1000;
377:     this.last = now;
378:     dt = clamp(dt, 0.001, 0.05);
379:     this.fpsAcc += dt;
380:     this.fpsFrames++;
381:     if (this.fpsAcc > 0.6) {
382:       this.fps = Math.round(this.fpsFrames / this.fpsAcc);
383:       this.fpsAcc = 0;
384:       this.fpsFrames = 0;
385:     }
386: 
387:     const geo = this.computeGeometry();
388:     ctx.clearRect(0, 0, this.w, this.h);
389:     this.drawBackground(geo, dt);
390:     this.drawBlock(geo);
391:     for (const g of geo.geos) this.drawCylinderBody(g);
392:     this.drawCrankshaft(geo);
393:     for (const g of geo.geos) this.drawRod(g);
394:     for (const g of geo.geos) this.drawPiston(g);
395:     for (const g of geo.geos) this.drawHead(g);
396:     for (const g of geo.geos) {
397:       this.updateFx(g, dt);
398:       this.drawChamberGlow(g);
399:     }
400:     for (const g of geo.geos) this.drawPorts(g);
401:     for (const g of geo.geos) this.drawFx(g);
402:     for (const g of geo.geos) this.drawLabels(g);
403:     this.drawForeground(geo);
404:   }
405: 
406:   drawBackground(geo, dt) {
407:     const ctx = this.ctx;
408:     const w = this.w;
409:     const h = this.h;
410: 
411:     const base = ctx.createRadialGradient(w * 0.5, h * 0.38, 10, w * 0.5, h * 0.45, Math.max(w, h) * 0.75);
412:     base.addColorStop(0, 'rgba(12, 52, 94, .22)');
413:     base.addColorStop(0.45, 'rgba(6, 24, 47, .08)');
414:     base.addColorStop(1, 'rgba(2, 7, 16, 0)');
415:     ctx.fillStyle = base;
416:     ctx.fillRect(0, 0, w, h);
417: 
418:     // Fine blueprint grid.
419:     ctx.save();
420:     ctx.strokeStyle = 'rgba(90, 160, 220, .05)';
421:     ctx.lineWidth = 1;
422:     const step = 38;
423:     const offX = (this.sim.time * 2) % step;
424:     for (let x = -step + offX; x < w + step; x += step) {
425:       ctx.beginPath();
426:       ctx.moveTo(x, 0);
427:       ctx.lineTo(x, h);
428:       ctx.stroke();
429:     }
430:     for (let y = 0; y < h; y += step) {
431:       ctx.beginPath();
432:       ctx.moveTo(0, y);
433:       ctx.lineTo(w, y);
434:       ctx.stroke();
435:     }
436:     ctx.restore();
437: 
438:     // Concentric targeting rings behind the engine.
439:     ctx.save();
440:     ctx.translate(w * 0.5, h * 0.44);
441:     for (let i = 0; i < 4; i++) {
442:       ctx.beginPath();
443:       ctx.arc(0, 0, 90 + i * 72, 0, TAU);
444:       ctx.strokeStyle = `rgba(56, 189, 248, ${0.035 - i * 0.006})`;
445:       ctx.lineWidth = 1;
446:       ctx.stroke();
447:     }
448:     ctx.restore();
449: 
450:     // Ambient dust.
451:     ctx.save();
452:     for (const d of this.dust) {
453:       d.x += d.vx * dt;
454:       d.y += d.vy * dt;
455:       if (d.y < -0.03) { d.y = 1.03; d.x = Math.random(); }
456:       if (d.x < -0.03) d.x = 1.03;
457:       if (d.x > 1.03) d.x = -0.03;
458:       const x = d.x * w;
459:       const y = d.y * h;
460:       const tw = 0.6 + 0.4 * Math.sin(this.sim.time * 1.7 + d.p);
461:       ctx.beginPath();
462:       ctx.arc(x, y, d.r, 0, TAU);
463:       ctx.fillStyle = `rgba(125, 211, 252, ${d.a * tw})`;
464:       ctx.fill();
465:     }
466:     ctx.restore();
467: 
468:     // Crankcase glow line.
469:     const glow = ctx.createLinearGradient(0, geo.crankY, w, geo.crankY);
470:     glow.addColorStop(0, 'rgba(56, 189, 248, 0)');
471:     glow.addColorStop(0.5, 'rgba(56, 189, 248, .18)');
472:     glow.addColorStop(1, 'rgba(56, 189, 248, 0)');
473:     ctx.strokeStyle = glow;
474:     ctx.lineWidth = 1;
475:     ctx.beginPath();
476:     ctx.moveTo(0, geo.crankY);
477:     ctx.lineTo(w, geo.crankY);
478:     ctx.stroke();
479:   }
480: 
481:   drawBlock(geo) {
482:     const ctx = this.ctx;
483:     const { blockX0, blockX1, blockTop, blockBottom, crankY, isVee } = geo;
484:     const w = blockX1 - blockX0;
485:     const h = blockBottom - blockTop;
486: 
487:     // Outer housing shadow (cheap offset, no blur).
488:     ctx.save();
489:     rr(ctx, blockX0, blockTop + 10, w, h, 18);
490:     ctx.fillStyle = 'rgba(0, 0, 0, .34)';
491:     ctx.fill();
492:     ctx.restore();
493: 
494:     rr(ctx, blockX0, blockTop, w, h, 18);
495:     const bodyGrad = ctx.createLinearGradient(blockX0, blockTop, blockX1, blockBottom);
496:     bodyGrad.addColorStop(0, 'rgba(15, 37, 63, .78)');
497:     bodyGrad.addColorStop(0.28, 'rgba(8, 24, 45, .82)');
498:     bodyGrad.addColorStop(0.72, 'rgba(6, 18, 35, .9)');
499:     bodyGrad.addColorStop(1, 'rgba(3, 10, 22, .94)');
500:     ctx.fillStyle = bodyGrad;
501:     ctx.fill();
502: 
503:     // Top and bottom rims.
504:     ctx.save();
505:     rr(ctx, blockX0, blockTop, w, h, 18);
506:     ctx.strokeStyle = 'rgba(96, 165, 250, .2)';
507:     ctx.lineWidth = 1;
508:     ctx.stroke();
509:     ctx.strokeStyle = 'rgba(125, 211, 252, .08)';
510:     ctx.lineWidth = 1;
511:     ctx.beginPath();
512:     ctx.moveTo(blockX0 + 14, blockTop + 1.5);
513:     ctx.lineTo(blockX1 - 14, blockTop + 1.5);
514:     ctx.stroke();
515:     ctx.restore();
516: 
517:     // Block ribs / seams.
518:     ctx.save();
519:     for (let i = 0; i <= geo.units; i++) {
520:       const x = geo.marginX + geo.spacing * i;
521:       ctx.beginPath();
522:       ctx.moveTo(x, blockTop + 14);
523:       ctx.lineTo(x, blockBottom - 10);
524:       ctx.strokeStyle = 'rgba(104, 174, 235, .06)';
525:       ctx.lineWidth = 1;
526:       ctx.stroke();
527:     }
528:     // horizontal machining lines
529:     for (let y = blockTop + 26; y < blockBottom - 16; y += 22) {
530:       ctx.beginPath();
531:       ctx.moveTo(blockX0 + 10, y);
532:       ctx.lineTo(blockX1 - 10, y);
533:       ctx.strokeStyle = 'rgba(104, 174, 235, .028)';
534:       ctx.lineWidth = 1;
535:       ctx.stroke();
536:     }
537:     ctx.restore();
538: 
539:     // Crankcase aperture.
540:     ctx.save();
541:     const caseTop = crankY - geo.strokePx * 0.58;
542:     const caseH = blockBottom - caseTop - 14;
543:     rr(ctx, blockX0 + 16, caseTop, w - 32, caseH, 12);
544:     const caseGrad = ctx.createLinearGradient(0, caseTop, 0, blockBottom);
545:     caseGrad.addColorStop(0, 'rgba(2, 8, 18, .82)');
546:     caseGrad.addColorStop(0.55, 'rgba(4, 14, 28, .9)');
547:     caseGrad.addColorStop(1, 'rgba(8, 22, 40, .85)');
548:     ctx.fillStyle = caseGrad;
549:     ctx.fill();
550:     ctx.strokeStyle = 'rgba(56, 189, 248, .1)';
551:     ctx.stroke();
552:     ctx.restore();
553: 
554:     // Oil pan glow.
555:     const panTop = blockBottom - 22;
556:     ctx.save();
557:     rr(ctx, blockX0 + 34, panTop, w - 68, 18, 8);
558:     const oil = ctx.createLinearGradient(0, panTop, 0, panTop + 18);
559:     oil.addColorStop(0, 'rgba(251, 146, 60, .03)');
560:     oil.addColorStop(0.5, 'rgba(251, 191, 36, .1)');
561:     oil.addColorStop(1, 'rgba(251, 146, 60, .02)');
562:     ctx.fillStyle = oil;
563:     ctx.fill();
564:     ctx.strokeStyle = 'rgba(251, 191, 36, .1)';
565:     ctx.lineWidth = 1;
566:     ctx.stroke();
567:     ctx.restore();
568: 
569:     // Bolts along the top and bottom rails.
570:     ctx.save();
571:     for (let i = 0; i < 9; i++) {
572:       const x = blockX0 + 22 + (w - 44) * (i / 8);
573:       this.drawBolt(x, blockTop + 9, 2.6);
574:       this.drawBolt(x, blockBottom - 8, 2.6);
575:     }
576:     ctx.restore();
577: 
578:     // Embossed block marking.
579:     ctx.save();
580:     ctx.font = '600 7px "DejaVu Sans Mono", monospace';
581:     ctx.fillStyle = 'rgba(125, 211, 252, .18)';
582:     ctx.textAlign = 'center';
583:     ctx.fillText('APEX // DYNO', this.w / 2, blockBottom - 11);
584:     ctx.restore();
585: 
586:     // V-valley highlight.
587:     if (isVee) {
588:       ctx.save();
589:       const grad = ctx.createLinearGradient(0, blockTop, 0, crankY);
590:       grad.addColorStop(0, 'rgba(56, 189, 248, .05)');
591:       grad.addColorStop(1, 'rgba(56, 189, 248, 0)');
592:       ctx.fillStyle = grad;
593:       ctx.beginPath();
594:       ctx.moveTo(blockX0 + 30, blockTop + 4);
595:       ctx.lineTo(this.w / 2, crankY - 30);
596:       ctx.lineTo(blockX1 - 30, blockTop + 4);
597:       ctx.closePath();
598:       ctx.fill();
599:       ctx.restore();
600:     }
601:   }
602: 
603:   drawBolt(x, y, r) {
604:     const ctx = this.ctx;
605:     ctx.beginPath();
606:     ctx.arc(x, y, r, 0, TAU);
607:     ctx.fillStyle = 'rgba(125, 155, 180, .35)';
608:     ctx.fill();
609:     ctx.strokeStyle = 'rgba(210, 235, 250, .25)';
610:     ctx.lineWidth = 0.6;
611:     ctx.stroke();
612:     ctx.beginPath();
613:     ctx.moveTo(x - r * 0.6, y);
614:     ctx.lineTo(x + r * 0.6, y);
615:     ctx.strokeStyle = 'rgba(2, 8, 18, .5)';
616:     ctx.stroke();
617:   }
618: 
619:   drawCylinderBody(g) {
620:     const ctx = this.ctx;
621:     const { bore, deckY, bottomY, headW } = g;
622:     ctx.save();
623:     ctx.translate(g.cx, g.crankY);
624:     ctx.rotate(g.bank);
625: 
626:     // Outer water jacket / liner.
627:     rr(ctx, -bore / 2 - 7, deckY - 2, bore + 14, bottomY - deckY + 4, 7);
628:     const jacket = ctx.createLinearGradient(-bore / 2 - 7, 0, bore / 2 + 7, 0);
629:     jacket.addColorStop(0, 'rgba(11, 32, 57, .82)');
630:     jacket.addColorStop(0.5, 'rgba(17, 44, 75, .55)');
631:     jacket.addColorStop(1, 'rgba(8, 24, 44, .82)');
632:     ctx.fillStyle = jacket;
633:     ctx.fill();
634:     ctx.strokeStyle = 'rgba(56, 189, 248, .18)';
635:     ctx.lineWidth = 1;
636:     ctx.stroke();
637: 
638:     // Cooling fins.
639:     ctx.save();
640:     ctx.strokeStyle = 'rgba(125, 211, 252, .09)';
641:     ctx.lineWidth = 1;
642:     for (let y = deckY + 28; y < bottomY - 8; y += 13) {
643:       ctx.beginPath();
644:       ctx.moveTo(-bore / 2 - 15, y);
645:       ctx.lineTo(-bore / 2 - 8, y);
646:       ctx.moveTo(bore / 2 + 8, y);
647:       ctx.lineTo(bore / 2 + 15, y);
648:       ctx.stroke();
649:     }
650:     ctx.restore();
651: 
652:     // Inner bore.
653:     rr(ctx, -bore / 2, deckY, bore, bottomY - deckY, 5);
654:     const boreGrad = ctx.createLinearGradient(-bore / 2, 0, bore / 2, 0);
655:     boreGrad.addColorStop(0, 'rgba(1, 6, 14, .98)');
656:     boreGrad.addColorStop(0.16, 'rgba(5, 17, 32, .98)');
657:     boreGrad.addColorStop(0.5, 'rgba(2, 9, 19, .96)');
658:     boreGrad.addColorStop(0.84, 'rgba(5, 17, 32, .98)');
659:     boreGrad.addColorStop(1, 'rgba(1, 6, 14, .98)');
660:     ctx.fillStyle = boreGrad;
661:     ctx.fill();
662:     ctx.strokeStyle = 'rgba(125, 211, 252, .2)';
663:     ctx.lineWidth = 1;
664:     ctx.stroke();
665: 
666:     // Cylinder wall highlight.
667:     ctx.beginPath();
668:     ctx.moveTo(-bore / 2 + 2, deckY + 3);
669:     ctx.lineTo(-bore / 2 + 2, bottomY - 3);
670:     ctx.strokeStyle = 'rgba(125, 211, 252, .08)';
671:     ctx.stroke();
672: 
673:     // Head deck plate.
674:     rr(ctx, -headW / 2, deckY - 4, headW, 8, 3);
675:     ctx.fillStyle = metallic(ctx, -headW / 2, 0, headW / 2, 0, 0.72);
676:     ctx.fill();
677:     ctx.strokeStyle = 'rgba(180, 220, 245, .25)';
678:     ctx.lineWidth = 0.8;
679:     ctx.stroke();
680: 
681:     ctx.restore();
