684:   drawCrankshaft(geo) {
685:     const ctx = this.ctx;
686:     const { crankY, blockX0, blockX1 } = geo;
687:     const x0 = blockX0 + 18;
688:     const x1 = blockX1 - 18;
689: 
690:     // Main shaft.
691:     ctx.save();
692:     const shaft = ctx.createLinearGradient(0, crankY - 8, 0, crankY + 8);
693:     shaft.addColorStop(0, 'rgba(170, 200, 220, .85)');
694:     shaft.addColorStop(0.28, 'rgba(232, 246, 255, .96)');
695:     shaft.addColorStop(0.55, 'rgba(104, 134, 158, .9)');
696:     shaft.addColorStop(1, 'rgba(48, 72, 96, .9)');
697:     rr(ctx, x0, crankY - 6, x1 - x0, 12, 6);
698:     ctx.fillStyle = shaft;
699:     ctx.fill();
700:     ctx.strokeStyle = 'rgba(190, 230, 250, .24)';
701:     ctx.lineWidth = 0.8;
702:     ctx.stroke();
703:     ctx.restore();
704: 
705:     // Main journals + throws.
706:     const seen = new Set();
707:     for (const g of geo.geos) {
708:       const key = geo.isVee ? g.cyl.pair : g.cyl.index;
709:       if (seen.has(key)) continue;
710:       seen.add(key);
711:       ctx.save();
712:       ctx.translate(g.cx, crankY);
713:       ctx.rotate(g.theta * DEG);
714: 
715:       // Counterweight.
716:       ctx.beginPath();
717:       ctx.arc(0, 0, g.r * 1.08, Math.PI / 2 - 0.68, Math.PI / 2 + 0.68);
718:       ctx.closePath();
719:       const cw = ctx.createLinearGradient(-g.r, g.r * 0.4, g.r, g.r * 1.2);
720:       cw.addColorStop(0, 'rgba(42, 64, 86, .96)');
721:       cw.addColorStop(0.45, 'rgba(104, 134, 158, .9)');
722:       cw.addColorStop(0.7, 'rgba(164, 192, 212, .82)');
723:       cw.addColorStop(1, 'rgba(38, 58, 80, .96)');
724:       ctx.fillStyle = cw;
725:       ctx.fill();
726:       ctx.strokeStyle = 'rgba(160, 210, 240, .28)';
727:       ctx.lineWidth = 1;
728:       ctx.stroke();
729: 
730:       // Web from center to pin.
731:       ctx.beginPath();
732:       ctx.moveTo(0, 0);
733:       ctx.lineTo(0, -g.r);
734:       ctx.strokeStyle = 'rgba(142, 176, 198, .9)';
735:       ctx.lineWidth = 11;
736:       ctx.lineCap = 'round';
737:       ctx.stroke();
738:       ctx.strokeStyle = 'rgba(230, 245, 255, .35)';
739:       ctx.lineWidth = 2.6;
740:       ctx.stroke();
741:       ctx.lineCap = 'butt';
742: 
743:       // Main journal.
744:       ctx.beginPath();
745:       ctx.arc(0, 0, 10, 0, TAU);
746:       ctx.fillStyle = metallic(ctx, -10, -10, 10, 10, 0.92);
747:       ctx.fill();
748:       ctx.strokeStyle = 'rgba(210, 240, 255, .35)';
749:       ctx.stroke();
750: 
751:       // Crank pin.
752:       const pinY = -g.r;
753:       const pinGlow = ctx.createRadialGradient(0, pinY, 1, 0, pinY, 15);
754:       pinGlow.addColorStop(0, 'rgba(125, 211, 252, .5)');
755:       pinGlow.addColorStop(1, 'rgba(56, 189, 248, 0)');
756:       ctx.fillStyle = pinGlow;
757:       ctx.beginPath();
758:       ctx.arc(0, pinY, 15, 0, TAU);
759:       ctx.fill();
760:       ctx.beginPath();
761:       ctx.arc(0, pinY, 8, 0, TAU);
762:       ctx.fillStyle = metallic(ctx, -8, pinY - 8, 8, pinY + 8, 0.9);
763:       ctx.fill();
764:       ctx.strokeStyle = 'rgba(220, 245, 255, .45)';
765:       ctx.stroke();
766: 
767:       ctx.restore();
768:     }
769: 
770:     // End caps.
771:     ctx.save();
772:     for (const x of [x0, x1]) {
773:       ctx.beginPath();
774:       ctx.arc(x, crankY, 9, 0, TAU);
775:       ctx.fillStyle = metallic(ctx, x - 9, crankY - 9, x + 9, crankY + 9, 0.7);
776:       ctx.fill();
777:       ctx.strokeStyle = 'rgba(190, 225, 245, .3)';
778:       ctx.stroke();
779:     }
780:     ctx.restore();
781:   }
