783:   drawRod(g) {
784:     const ctx = this.ctx;
785:     const px = g.localPin.x;
786:     const py = g.localPin.y;
787:     const sx = 0;
788:     const sy = g.pinY;
789:     const dx = sx - px;
790:     const dy = sy - py;
791:     const len = Math.hypot(dx, dy) || 1;
792:     const ux = dx / len;
793:     const uy = dy / len;
794:     const nx = -uy;
795:     const ny = ux;
796:     const wBig = Math.max(5, g.bore * 0.075);
797:     const wSmall = Math.max(3.4, g.bore * 0.048);
798: 
799:     ctx.save();
800:     ctx.translate(g.cx, g.crankY);
801:     ctx.rotate(g.bank);
802: 
803:     // Rod shadow.
804:     ctx.beginPath();
805:     ctx.moveTo(px + nx * wBig, py + ny * wBig);
806:     ctx.lineTo(sx + nx * wSmall, sy + ny * wSmall);
807:     ctx.lineTo(sx - nx * wSmall, sy - ny * wSmall);
808:     ctx.lineTo(px - nx * wBig, py - ny * wBig);
809:     ctx.closePath();
810:     ctx.fillStyle = 'rgba(0, 0, 0, .45)';
811:     ctx.fill();
812: 
813:     // Rod body.
814:     ctx.beginPath();
815:     ctx.moveTo(px + nx * wBig, py + ny * wBig);
816:     ctx.lineTo(sx + nx * wSmall, sy + ny * wSmall);
817:     ctx.lineTo(sx - nx * wSmall, sy - ny * wSmall);
818:     ctx.lineTo(px - nx * wBig, py - ny * wBig);
819:     ctx.closePath();
820:     const rodGrad = ctx.createLinearGradient(px, py, sx, sy);
821:     rodGrad.addColorStop(0, 'rgba(74, 98, 120, .98)');
822:     rodGrad.addColorStop(0.25, 'rgba(188, 214, 232, .98)');
823:     rodGrad.addColorStop(0.5, 'rgba(118, 146, 168, .98)');
824:     rodGrad.addColorStop(0.76, 'rgba(214, 235, 248, .98)');
825:     rodGrad.addColorStop(1, 'rgba(82, 108, 130, .98)');
826:     ctx.fillStyle = rodGrad;
827:     ctx.fill();
828:     ctx.strokeStyle = 'rgba(220, 245, 255, .22)';
829:     ctx.lineWidth = 0.7;
830:     ctx.stroke();
831: 
832:     // I-beam center line.
833:     ctx.beginPath();
834:     ctx.moveTo(px + nx * 1.2, py + ny * 1.2);
835:     ctx.lineTo(sx + nx * 0.7, sy + ny * 0.7);
836:     ctx.strokeStyle = 'rgba(20, 38, 56, .55)';
837:     ctx.lineWidth = Math.max(1.2, g.bore * 0.018);
838:     ctx.stroke();
839: 
840:     // Big end.
841:     ctx.beginPath();
842:     ctx.arc(px, py, wBig + 2.4, 0, TAU);
843:     ctx.fillStyle = metallic(ctx, px - wBig, py - wBig, px + wBig, py + wBig, 0.78);
844:     ctx.fill();
845:     ctx.strokeStyle = 'rgba(210, 240, 255, .3)';
846:     ctx.lineWidth = 0.8;
847:     ctx.stroke();
848:     ctx.beginPath();
849:     ctx.arc(px, py, wBig * 0.45, 0, TAU);
850:     ctx.fillStyle = 'rgba(3, 11, 22, .85)';
851:     ctx.fill();
852: 
853:     // Small end.
854:     ctx.beginPath();
855:     ctx.arc(sx, sy, wSmall + 1.6, 0, TAU);
856:     ctx.fillStyle = metallic(ctx, sx - wSmall, sy - wSmall, sx + wSmall, sy + wSmall, 0.85);
857:     ctx.fill();
858:     ctx.beginPath();
859:     ctx.arc(sx, sy, wSmall * 0.48, 0, TAU);
860:     ctx.fillStyle = 'rgba(3, 11, 22, .85)';
861:     ctx.fill();
862: 
863:     ctx.restore();
864:   }
