866:   drawPiston(g) {
867:     const ctx = this.ctx;
868:     const slap = this.sim.pistonSlap;
869:     const jitter = Math.sin(this.sim.time * 92 + g.cyl.index * 2.2) * slap * 1.6;
870:     ctx.save();
871:     ctx.translate(g.cx, g.crankY);
872:     ctx.rotate(g.bank);
873:     ctx.translate(jitter, g.pinY);
874: 
875:     const bw = g.bore - 3;
876:     const bh = g.pistonH;
877:     const left = -bw / 2;
878:     const top = -bh / 2;
879: 
880:     // Piston shadow (cheap offset).
881:     rr(ctx, left + 2, top + 3, bw, bh, 3.5);
882:     ctx.fillStyle = 'rgba(0, 0, 0, .35)';
883:     ctx.fill();
884: 
885:     // Piston body.
886:     rr(ctx, left, top, bw, bh, 3.5);
887:     const grad = ctx.createLinearGradient(left, 0, left + bw, 0);
888:     grad.addColorStop(0, '#3a5068');
889:     grad.addColorStop(0.16, '#a9c2d4');
890:     grad.addColorStop(0.34, '#eef9ff');
891:     grad.addColorStop(0.52, '#a5bfd2');
892:     grad.addColorStop(0.7, '#d8eaf6');
893:     grad.addColorStop(0.86, '#7d99ae');
894:     grad.addColorStop(1, '#2d435a');
895:     ctx.fillStyle = grad;
896:     ctx.fill();
897:     ctx.strokeStyle = 'rgba(225, 246, 255, .5)';
898:     ctx.lineWidth = 0.8;
899:     ctx.stroke();
900: 
901:     // Crown highlight / heat tint.
902:     const heat = g.cyl.combustion;
903:     ctx.beginPath();
904:     ctx.moveTo(left + 2, top + 2.5);
905:     ctx.lineTo(left + bw - 2, top + 2.5);
906:     ctx.strokeStyle = heat > 0.04
907:       ? `rgba(255, 190, 96, ${0.5 + heat * 0.5})`
908:       : 'rgba(210, 240, 255, .55)';
909:     ctx.lineWidth = heat > 0.04 ? 1.8 : 1;
910:     ctx.stroke();
911:     if (heat > 0.04) {
912:       ctx.strokeStyle = `rgba(255, 200, 120, ${heat * 0.8})`;
913:       ctx.lineWidth = 3.2;
914:       ctx.beginPath();
915:       ctx.moveTo(left + 2, top + 1.6);
916:       ctx.lineTo(left + bw - 2, top + 1.6);
917:       ctx.stroke();
918:       ctx.strokeStyle = `rgba(255, 248, 220, ${heat * 0.7})`;
919:       ctx.lineWidth = 1.2;
920:       ctx.stroke();
921:     }
922: 
923:     // Rings.
924:     for (let i = 0; i < 3; i++) {
925:       const y = top + 4 + i * 3.2;
926:       ctx.beginPath();
927:       ctx.moveTo(left + 2, y);
928:       ctx.lineTo(left + bw - 2, y);
929:       ctx.strokeStyle = 'rgba(14, 30, 46, .62)';
930:       ctx.lineWidth = 1.1;
931:       ctx.stroke();
932:       ctx.beginPath();
933:       ctx.moveTo(left + 2, y + 0.7);
934:       ctx.lineTo(left + bw - 2, y + 0.7);
935:       ctx.strokeStyle = 'rgba(235, 248, 255, .22)';
936:       ctx.lineWidth = 0.6;
937:       ctx.stroke();
938:     }
939: 
940:     // Skirt reliefs.
941:     ctx.beginPath();
942:     rr(ctx, left + 3, top + bh * 0.58, bw * 0.2, bh * 0.34, 2);
943:     ctx.fillStyle = 'rgba(9, 24, 40, .5)';
944:     ctx.fill();
945:     ctx.beginPath();
946:     rr(ctx, left + bw - 3 - bw * 0.2, top + bh * 0.58, bw * 0.2, bh * 0.34, 2);
947:     ctx.fillStyle = 'rgba(9, 24, 40, .5)';
948:     ctx.fill();
949: 
950:     // Wrist pin.
951:     ctx.beginPath();
952:     ctx.arc(0, 0, Math.max(2.2, bh * 0.13), 0, TAU);
953:     ctx.fillStyle = metallic(ctx, -bh * 0.13, -bh * 0.13, bh * 0.13, bh * 0.13, 0.7);
954:     ctx.fill();
955:     ctx.strokeStyle = 'rgba(20, 42, 62, .8)';
956:     ctx.lineWidth = 0.8;
957:     ctx.stroke();
958:     ctx.beginPath();
959:     ctx.arc(0, 0, Math.max(1, bh * 0.055), 0, TAU);
960:     ctx.fillStyle = 'rgba(2, 8, 16, .85)';
961:     ctx.fill();
962: 
963:     ctx.restore();
964:   }
