966:   drawHead(g) {
967:     const ctx = this.ctx;
968:     const { headW, headH, headTop, deckY, bore } = g;
969:     ctx.save();
970:     ctx.translate(g.cx, g.crankY);
971:     ctx.rotate(g.bank);
972: 
973:     // Head shell.
974:     rr(ctx, -headW / 2, headTop, headW, headH, 7);
975:     const shell = ctx.createLinearGradient(-headW / 2, headTop, headW / 2, deckY);
976:     shell.addColorStop(0, 'rgba(30, 63, 98, .98)');
977:     shell.addColorStop(0.35, 'rgba(17, 43, 73, .98)');
978:     shell.addColorStop(0.7, 'rgba(24, 55, 89, .97)');
979:     shell.addColorStop(1, 'rgba(9, 26, 47, .98)');
980:     ctx.fillStyle = shell;
981:     ctx.fill();
982:     ctx.strokeStyle = 'rgba(125, 211, 252, .3)';
983:     ctx.lineWidth = 1;
984:     ctx.stroke();
985: 
986:     // Head top highlight.
987:     ctx.beginPath();
988:     ctx.moveTo(-headW / 2 + 7, headTop + 1.6);
989:     ctx.lineTo(headW / 2 - 7, headTop + 1.6);
990:     ctx.strokeStyle = 'rgba(190, 230, 255, .32)';
991:     ctx.lineWidth = 1;
992:     ctx.stroke();
993: 
994:     // Cam cover rail.
995:     rr(ctx, -headW / 2 + 4, headTop + 3, headW - 8, 7, 3);
996:     const cover = ctx.createLinearGradient(0, headTop + 3, 0, headTop + 10);
997:     cover.addColorStop(0, 'rgba(112, 146, 172, .92)');
998:     cover.addColorStop(0.4, 'rgba(204, 228, 242, .95)');
999:     cover.addColorStop(1, 'rgba(54, 82, 108, .92)');
1000:     ctx.fillStyle = cover;
1001:     ctx.fill();
1002:     ctx.strokeStyle = 'rgba(220, 245, 255, .3)';
1003:     ctx.lineWidth = 0.6;
1004:     ctx.stroke();
1005: 
1006:     // Cutaway window.
1007:     const winX = -headW / 2 + 7;
1008:     const winY = headTop + 11;
1009:     const winW = headW - 14;
1010:     const winH = headH - 19;
1011:     rr(ctx, winX, winY, winW, winH, 4);
1012:     const win = ctx.createLinearGradient(0, winY, 0, winY + winH);
1013:     win.addColorStop(0, 'rgba(4, 14, 28, .92)');
1014:     win.addColorStop(0.5, 'rgba(9, 27, 49, .86)');
1015:     win.addColorStop(1, 'rgba(2, 8, 18, .94)');
1016:     ctx.fillStyle = win;
1017:     ctx.fill();
1018:     ctx.strokeStyle = 'rgba(56, 189, 248, .2)';
1019:     ctx.stroke();
1020: 
1021:     // Camshafts.
1022:     const camR = Math.max(4.4, bore * 0.072);
1023:     this.drawCam(-bore * 0.26, g.camY, camR, g.camAngle, '#a8e2ff');
1024:     this.drawCam(bore * 0.26, g.camY, camR, g.camAngle + Math.PI, '#ffd9a8');
1025: 
1026:     // Cam bearing caps.
1027:     ctx.save();
1028:     ctx.strokeStyle = 'rgba(125, 211, 252, .22)';
1029:     ctx.lineWidth = 1;
1030:     ctx.beginPath();
1031:     ctx.moveTo(-headW / 2 + 12, g.camY - camR - 4);
1032:     ctx.lineTo(headW / 2 - 12, g.camY - camR - 4);
1033:     ctx.stroke();
1034:     ctx.restore();
1035: 
1036:     // Valve seats.
1037:     const seat = bore * 0.28;
1038:     const seatGlow = (x, color) => {
1039:       ctx.beginPath();
1040:       ctx.ellipse(x, deckY, Math.max(5, bore * 0.085), Math.max(1.8, bore * 0.03), 0, 0, TAU);
1041:       ctx.fillStyle = color;
1042:       ctx.fill();
1043:     };
1044:     seatGlow(-seat, 'rgba(56, 189, 248, .24)');
1045:     seatGlow(seat, 'rgba(251, 146, 60, .24)');
1046: 
1047:     // Valves.
1048:     const maxLift = Math.max(6, bore * 0.14);
1049:     this.drawValve(-seat, deckY, -0.2, g.cyl.intakeLift * maxLift, headH, true);
1050:     this.drawValve(seat, deckY, 0.2, g.cyl.exhaustLift * maxLift, headH, false);
1051: 
1052:     // Springs.
1053:     this.drawSpring(-seat + 1, deckY - headH * 0.16, deckY - headH * 0.56, 5.2, 5, g.cyl.intakeLift);
1054:     this.drawSpring(seat - 1, deckY - headH * 0.16, deckY - headH * 0.56, 5.2, 5, g.cyl.exhaustLift);
1055: 
1056:     // Spark plug.
1057:     this.drawSparkPlug(g);
1058: 
1059:     // Head bolts.
1060:     for (const [x, y] of [[-headW / 2 + 5, headTop + 5], [headW / 2 - 5, headTop + 5], [-headW / 2 + 5, deckY - 5], [headW / 2 - 5, deckY - 5]]) {
1061:       this.drawBolt(x, y, 1.8);
1062:     }
1063: 
1064:     ctx.restore();
1065:   }
