1070:     ctx.translate(x, y);
1071:     ctx.rotate(angle);
1072:     // Lobe.
1073:     ctx.beginPath();
1074:     ctx.ellipse(0, -r * 0.72, r * 0.66, r * 1.25, 0, 0, TAU);
1075:     const lobe = ctx.createLinearGradient(-r, -r, r, r);
1076:     lobe.addColorStop(0, 'rgba(58, 88, 112, .98)');
1077:     lobe.addColorStop(0.45, color);
1078:     lobe.addColorStop(1, 'rgba(42, 68, 92, .98)');
1079:     ctx.fillStyle = lobe;
1080:     ctx.fill();
1081:     ctx.strokeStyle = 'rgba(220, 245, 255, .3)';
1082:     ctx.lineWidth = 0.6;
1083:     ctx.stroke();
1084:     // Base circle.
1085:     ctx.beginPath();
1086:     ctx.arc(0, 0, r, 0, TAU);
1087:     ctx.fillStyle = metallic(ctx, -r, -r, r, r, 0.78);
1088:     ctx.fill();
1089:     ctx.strokeStyle = 'rgba(220, 245, 255, .25)';
1090:     ctx.stroke();
1091:     ctx.beginPath();
1092:     ctx.arc(0, 0, r * 0.28, 0, TAU);
1093:     ctx.fillStyle = 'rgba(4, 14, 27, .8)';
1094:     ctx.fill();
1095:     ctx.restore();
1096:   }
