1098:   drawValve(x, y, angle, lift, headH, intake) {
1099:     const ctx = this.ctx;
1100:     const stemLen = headH * 0.64;
1101:     ctx.save();
1102:     ctx.translate(x, y + lift);
1103:     ctx.rotate(angle);
1104: 
1105:     // Valve head.
1106:     ctx.beginPath();
1107:     ctx.ellipse(0, 0, Math.max(5.5, headH * 0.12), Math.max(1.8, headH * 0.04), 0, 0, TAU);
1108:     const vg = ctx.createLinearGradient(-8, -3, 8, 3);
1109:     vg.addColorStop(0, 'rgba(66, 92, 116, .98)');
1110:     vg.addColorStop(0.45, 'rgba(235, 248, 255, .98)');
1111:     vg.addColorStop(1, 'rgba(64, 88, 110, .98)');
1112:     ctx.fillStyle = vg;
1113:     ctx.fill();
1114:     ctx.strokeStyle = 'rgba(230, 248, 255, .4)';
1115:     ctx.lineWidth = 0.6;
1116:     ctx.stroke();
1117: 
1118:     // Stem.
1119:     ctx.beginPath();
1120:     ctx.moveTo(0, -2);
1121:     ctx.lineTo(0, -stemLen);
1122:     ctx.strokeStyle = intake ? 'rgba(125, 211, 252, .8)' : 'rgba(251, 191, 146, .8)';
1123:     ctx.lineWidth = 2;
1124:     ctx.stroke();
1125:     ctx.strokeStyle = 'rgba(240, 250, 255, .35)';
1126:     ctx.lineWidth = 0.6;
1127:     ctx.stroke();
1128: 
1129:     // Retainer and follower.
1130:     ctx.beginPath();
1131:     ctx.moveTo(-3.8, -stemLen + 2);
1132:     ctx.lineTo(3.8, -stemLen + 2);
1133:     ctx.strokeStyle = 'rgba(190, 220, 240, .65)';
1134:     ctx.lineWidth = 1.8;
1135:     ctx.stroke();
1136:     ctx.beginPath();
1137:     ctx.arc(0, -stemLen, 2.6, 0, TAU);
1138:     ctx.fillStyle = metallic(ctx, -3, -stemLen - 3, 3, -stemLen + 3, 0.82);
1139:     ctx.fill();
1140:     ctx.strokeStyle = 'rgba(220, 245, 255, .3)';
1141:     ctx.lineWidth = 0.6;
1142:     ctx.stroke();
1143: 
1144:     ctx.restore();
1145:   }
1146: 
1147:   drawSpring(x, yTop, yBottom, width, coils, lift) {
1148:     const ctx = this.ctx;
1149:     const bottom = yBottom + lift * 3.5;
1150:     ctx.save();
1151:     ctx.beginPath();
1152:     const steps = coils * 2;
1153:     for (let i = 0; i <= steps; i++) {
1154:       const t = i / steps;
1155:       const y = yTop + (bottom - yTop) * t;
1156:       const px = x + (i % 2 === 0 ? -width : width) * (i === 0 || i === steps ? 0.3 : 1);
1157:       if (i === 0) ctx.moveTo(px, y);
1158:       else ctx.lineTo(px, y);
1159:     }
1160:     ctx.strokeStyle = 'rgba(150, 185, 208, .45)';
1161:     ctx.lineWidth = 0.9;
1162:     ctx.stroke();
1163:     ctx.restore();
1164:   }
1165: 
