import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs'

const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] })

async function shot(name, viewport, preset) {
  const page = await browser.newPage({ viewport, deviceScaleFactor: 2 })
  page.on('pageerror', e => console.log('[pageerror]', name, e.message))
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' })
  await page.waitForTimeout(500)
  if (preset) {
    await page.click(`.preset-btn[data-preset="${preset}"]`)
    await page.waitForTimeout(900)
  }
  const canvas = await page.$('#engineCanvas')
  if (canvas) await canvas.screenshot({ path: `screenshots/${name}-canvas.png` })
  await page.screenshot({ path: `screenshots/${name}.jpg`, type: 'jpeg', quality: 80 })
  const info = await page.evaluate(() => {
    const q = s => { const e = document.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect(); return { top: Math.round(r.top), bottom: Math.round(r.bottom), h: Math.round(r.height), scrollH: e.scrollHeight, clientH: e.clientHeight } }
    return {
      vw: innerWidth, vh: innerHeight,
      bodyW: document.body.scrollWidth, bodyH: document.body.scrollHeight,
      leftRail: q('.left-rail'), rightRail: q('.right-rail'), stage: q('.stage'),
      hud: q('.hud-rail'), fluid: q('[data-panel="fluid"]')
    }
  })
  console.log(name, JSON.stringify(info))
  await page.close()
}

await shot('i4', { width: 1280, height: 900 })
